'@

$ExpectedSha256 = '0d028b707d67bb76ee6f53fb54a6c6274cb6981f7e94596ffebc440633de5b0a'
$ZipBytes = [Convert]::FromBase64String(($Base64Zip -replace '\s', ''))
$Sha = [System.Security.Cryptography.SHA256]::Create()
try {
    $ActualSha256 = [System.BitConverter]::ToString($Sha.ComputeHash($ZipBytes)).Replace('-', '').ToLowerInvariant()
}
finally {
    $Sha.Dispose()
}
if ($ActualSha256 -ne $ExpectedSha256) {
    throw "Embedded ZIP checksum mismatch. Expected $ExpectedSha256 but got $ActualSha256."
}

if ((Test-Path -LiteralPath $Destination) -and -not $Force) {
    throw "Destination '$Destination' already exists. Re-run with -Force to overwrite files."
}

New-Item -ItemType Directory -Path $Destination -Force | Out-Null
$TempZip = Join-Path ([System.IO.Path]::GetTempPath()) ('cdt-workflow-restore-' + [guid]::NewGuid().ToString('N') + '.zip')
try {
    [System.IO.File]::WriteAllBytes($TempZip, $ZipBytes)
    Expand-Archive -LiteralPath $TempZip -DestinationPath $Destination -Force
}
finally {
    if (Test-Path -LiteralPath $TempZip) {
        Remove-Item -LiteralPath $TempZip -Force
    }
}

Write-Host "Restored cdt-workflow to $Destination"
